window.kbPageData["views/entry/k-f97866c86d170578"] = {"key":"entry/k-f97866c86d170578","state":{"route":"entry/k-f97866c86d170578"},"node":{"id":"k-f97866c86d170578","mode":"k","title":"第四次全国农业普查","type":"事实与事件","domain":"统计","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["rural"],"主类":["事实与事件"],"出处性质":["机构注释"],"学科":["统计"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"4.第四次全国农业普查\n全国农业普查每 10 年进行一次。\n第四次全国农业普查的对象是在中华人民共和国境内的下列个人和单位：农村住户，包\n括农村农业生产经营户和其他住户；城镇农业生产经营户；农业生产经营单位；村民委员会；\n乡镇人民政府。\n普查的行业范围包括：农作物种植业、林业、畜牧业、渔业和农林牧渔…","sources":[{"id":"0d69b0759e55e811","label":"第四次全国农业普查","topic":"年度政府工作","category":"时政","text":"4.第四次全国农业普查\n全国农业普查每 10 年进行一次。\n第四次全国农业普查的对象是在中华人民共和国境内的下列个人和单位：农村住户，包\n括农村农业生产经营户和其他住户；城镇农业生产经营户；农业生产经营单位；村民委员会；\n乡镇人民政府。\n普查的行业范围包括：农作物种植业、林业、畜牧业、渔业和农林牧渔服务业。\n普查的主要内容包括：农业生产条件、粮食和大食物生产情况、农业新质生产力情况、\n乡村发展基本情况、农村居民生活情况等。\n普查的标准时点为 2026 年 12 月 31 日 24 时，时期资料为 2026 年年度资料。","source":{"doc":"6cbfb01fe723bba64b75","first":36,"last":36,"page":36,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-f97866c86d170578":[]}};
